        return '<div class="plan-row">'+btn('<span><strong>'+esc(saved?.name||planLabel(recent.plan))+'</strong><small>'+esc(saved?planLabel(recent.plan):repeat?'Used twice. Save as preset?':'Use this setup again')+'</small></span>','recent-run:'+index,'plan-run','play')+'<button class="icon-button" data-action="recent-save:'+index+'" aria-label="'+(saved?'Edit preset':'Save preset')+'">'+icon(saved?'sliders':'bookmark')+'</button></div>';
