    function appearance(){header('Appearance');main.innerHTML='<div class="content"><h1>Appearance</h1><div class="group">'+row('Typeface','typography','book','Fraunces titles · Newsreader reading','')+row('Reading size','reading-size','sliders','Headline scale stays restrained',state.readingSize+'px')+'</div><div class="group"><label class="check-row"><input type="checkbox" data-setting="eink" '+(state.eink?'checked':'')+'><span class="copy">E-ink presentation<small>Light paper, dark text, grayscale, immediate changes.</small></span></label></div><div class="font-preview"><div class="lab-label">Live reading sample</div><h3>'+esc(current().title)+'</h3><p>'+esc(current().teaser)+'</p></div><p class="fine">The production appearance controls for measure, spacing, card detail and image preferences remain in scope. This round focuses on type and the Afterglow surfaces.</p></div>';instrument({left:'sun',leftAction:'typography',label:'Type & reading',action:'typography',right:'Done',rightAction:'nav:you',rightIcon:'check'});}
