    function render(){tickActivity();if(route==='session-review')state.reviewScroll=main.scrollTop;const previousRoute=route;rendering=true;pause();if(sheet.open)closeSheet(false);if(viewer.open)closeImage(false);window.dispatchEvent(new Event("otium:navigate"));observer?.disconnect();route=decodeURIComponent(location.hash.slice(1)||'start');if(!['setup','setup-topics'].includes(route))editingPreset=null;const [view,...rest]=route.split('/'),key=rest.join('/');main.className='';main.scrollTop=0;bottom.hidden=false;({session,home,start,setup,'setup-topics':setupTopics,library,you,history,insights,appearance,settings,add,import:importPage,end:ending,'session-review':sessionReview}[view]||(()=>{if(view==='reader')reader(key);else if(view==='section')section(key);else if(view==='topic')topic(key);else if(view==='source')source(key);else if(view==='saved')saved();else if(view==='collection')saved(key);else home();}))();applyFont();if(previousRoute&&previousRoute!==route&&motionAllowed())main.animate([{opacity:.4,transform:'translateX(6px)'},{opacity:1,transform:'translateX(0)'}],{duration:170,easing:'ease-out'});if(view!=='session')rendering=false;if(view==='session-review')main.scrollTop=state.reviewScroll||0;tickActivity();}
    function sourceName(){if(route.startsWith('source/'))return decodeURIComponent(route.slice(7));return (route.startsWith('reader/')?article(route.slice(7)):current()).source;}
    function articleMenu(){const a=route.startsWith('reader/')?article(route.slice(7)):current();showSheet('This article','<p class="meta">'+esc(a.source)+'</p><h3 style="margin-top:4px">'+esc(a.title)+'</h3><div class="group">'+row('Save to a collection','save','bookmark','')+row('Share article','share','share')+(!a.kind?row('View full image','image:'+a.id,'search'):'')+row('Why this appeared','why','sliders')+row('About this source','source-current','book')+'</div><div class="group">'+row('Change representation','representation','sliders','Source frequency')+row('Categories & keywords','filters','sliders','Fine-tune what makes it into a session')+'</div>');}
