    document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b){e.preventDefault();action(b.dataset.action);}});
    document.addEventListener('change',e=>{const t=e.target;if(t.id==='plan-scope'){state.scope=t.value;state.excluded=[];persist();setup();return;}if(t.dataset.setting){state[t.dataset.setting]=t.checked;applyFont();}if(t.dataset.collection){const id=t.dataset.item,c=t.dataset.collection;const values=state.saved[id]||[];if(t.checked&&!values.length)state.savedAt[id]=Date.now();state.saved[id]=t.checked?[...new Set([...values,c])]:values.filter(x=>x!==c);if(t.checked)engageItem(id);persist();updateReviewBookmarks();}if(t.dataset.topic){state.excluded=t.checked?state.excluded.filter(x=>x!==t.dataset.topic):[...new Set([...state.excluded,t.dataset.topic])];persist();if(route==='setup-topics'||route==='setup')setup();}});
